def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        # Check if intervals overlap or touch
        if current_start <= last_end:
            # Merge them by updating the end of the last interval
            merged[-1] = (last_start, max(last_end, current_end))
        else:
            # No overlap, add the current interval to the list
            merged.append((current_start, current_end))

    return merged

def parse_csv_line(line):
    fields = []
    current_field = []
    in_quotes = False

    i = 0
    n = len(line)

    while i < n:
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check for escaped quote ""
                if i + 1 < n and line[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                    continue
                else:
                    # End of quoted field
                    in_quotes = False
            else:
                current_field.append(char)
        else:
            if char == '"':
                # Start of a quoted field
                in_quotes = True
            elif char == ',':
                # End of current field
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)

        i += 1

    # After loop, if we are still inside quotes, it's an error
    if in_quotes:
        raise ValueError("Unclosed quote")

    # Append the last field
    fields.append(''.join(current_field))

    return fields

def compare_versions(a: str, b: str) -> int:
    """
    Compare two version strings by Semantic Versioning precedence.

    Returns:
        -1 if a < b
         0 if a == b
         1 if a > b

    Format: MAJOR.MINOR.PATCH[-pre-release][+build-metadata]
    Build metadata is ignored.
    """
    def parse_version(version_str):
        # Split into core and optional parts
        pre_release = None
        build_metadata = None

        # Check for pre-release
        if '-' in version_str:
            core, rest = version_str.split('-', 1)
            # Check for build metadata after pre-release
            if '+' in rest:
                pre_release, build_metadata = rest.split('+', 1)
            else:
                pre_release = rest
        elif '+' in version_str:
            # Only build metadata, no pre-release
            core, build_metadata = version_str.split('+', 1)
        else:
            core = version_str

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, pre_release, build_metadata)

    def compare_pre_release(pre_a, pre_b):
        # If one is None, the one without pre-release is higher
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1  # a > b (a has no pre-release)
        if pre_b is None:
            return -1  # a < b (b has no pre-release)

        # Split into identifiers
        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')

        min_len = min(len(ids_a), len(ids_b))

        for i in range(min_len):
            id_a = ids_a[i]
            id_b = ids_b[i]

            # Check if identifiers are numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            if is_num_a and is_num_b:
                # Both numeric, compare as integers
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            else:
                # At least one is text, compare as strings
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        # All shared identifiers are equal, shorter list is lower
        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1

        return 0

    ver_a = parse_version(a)
    ver_b = parse_version(b)

    # Compare major, minor, patch
    if ver_a[0] != ver_b[0]:
        return -1 if ver_a[0] < ver_b[0] else 1
    if ver_a[1] != ver_b[1]:
        return -1 if ver_a[1] < ver_b[1] else 1
    if ver_a[2] != ver_b[2]:
        return -1 if ver_a[2] < ver_b[2] else 1

    # Compare pre-release
    return compare_pre_release(ver_a[3], ver_b[3])

