class LRUCache:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key in self.cache:
            # Move the accessed item to the end (most recently used)
            self.cache.move_to_end(key)
            return self.cache[key]
        return None

    def put(self, key, value):
        if key in self.cache:
            # Update the value and move to the end (most recently used)
            self.cache[key] = value
            self.cache.move_to_end(key)
        else:
            # Insert new item at the end
            self.cache[key] = value
            # If over capacity, remove the least recently used item (first item)
            if len(self.cache) > self.capacity:
                self.cache.popitem(last=False)

    def __len__(self):
        return len(self.cache)

    def keys(self):
        # Return keys from least recently used to most recently used
        return list(self.cache.keys())

def flatten_dict(d, sep="."):
    """
    Flattens a nested dictionary into a single-level dictionary.

    Args:
        d (dict): The input dictionary to flatten.
        sep (str): The separator to use between keys in the flattened result.

    Returns:
        dict: A flattened dictionary where nested keys are joined with the separator.
    """
    result = {}

    def _flatten(current_dict, prefix=""):
        for key, value in current_dict.items():
            new_key = f"{prefix}{sep}{key}" if prefix else key

            if isinstance(value, dict):
                # If the nested dictionary is empty, keep it as an empty dict under its key
                if not value:
                    result[new_key] = {}
                else:
                    _flatten(value, new_key)
            else:
                # Lists and other values are kept as they are
                result[new_key] = value

    _flatten(d)
    return result

def median(values):
    if not values:
        raise ValueError("median() arg is an empty list")
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2

def chunked(items, size):
    if size < 1:
        raise ValueError("size must be at least 1")
    return [list(items[i:i + size]) for i in range(0, len(items), size)]

def append_unique(item, bucket=None):
    if bucket is None:
        bucket = []
    if item not in bucket:
        bucket.append(item)
    return bucket

