class TTLCache:
    def __init__(self, capacity, ttl, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be greater than 0")

        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache = OrderedDict()

    def _is_expired(self, key):
        current_time = self._clock()
        return current_time >= self._cache[key]['expiry']

    def _remove_expired(self):
        # Remove all expired entries from the cache
        keys_to_remove = [key for key in self._cache if self._is_expired(key)]
        for key in keys_to_remove:
            del self._cache[key]

    def put(self, key, value):
        current_time = self._clock()

        # If key exists, update expiry time and move to end (most recently used)
        if key in self._cache:
            self._cache[key]['expiry'] = current_time + self._ttl
            self._cache.move_to_end(key)
        else:
            # New entry
            self._cache[key] = {'value': value, 'expiry': current_time + self._ttl}

        # Check capacity and evict if necessary
        while len(self._cache) > self._capacity:
            # First, try to remove expired entries
            expired_keys = [key for key in self._cache if self._is_expired(key)]

            if expired_keys:
                # Remove the oldest expired entry (first in OrderedDict)
                # We need to find the first expired key and remove it
                for key in list(self._cache.keys()):
                    if self._is_expired(key):
                        del self._cache[key]
                        break
            else:
                # No expired entries, remove the least recently used (first in OrderedDict)
                oldest_key = next(iter(self._cache))
                del self._cache[oldest_key]

    def get(self, key):
        if key not in self._cache:
            return None

        if self._is_expired(key):
            del self._cache[key]
            return None

        # Move to end (most recently used)
        self._cache.move_to_end(key)
        return self._cache[key]['value']

    def __len__(self):
        current_time = self._clock()
        count = 0
        for key in self._cache:
            if current_time < self._cache[key]['expiry']:
                count += 1
        return count

    def keys(self):
        current_time = self._clock()
        valid_keys = []
        for key in self._cache:
            if current_time < self._cache[key]['expiry']:
                valid_keys.append(key)

        # Sort by time of last use (position in OrderedDict)
        # Since OrderedDict maintains insertion order, and we move to end on access,
        # the order is already from least recently used to most recently used
        return valid_keys

