from typing import Dict, List, Tuple, Union, Optional

class Token:
    def __init__(self, type_: str, value: Union[str, float]):
        self.type = type_
        self.value = value

def tokenize(expr: str) -> List[Token]:
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or c == '.':
            start = i
            has_dot = False
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                if expr[i] == '.':
                    if has_dot:
                        raise ValueError("Multiple decimal points in number")
                    has_dot = True
                i += 1
            num_str = expr[start:i]
            # Validate number format: no leading dot without digit, no trailing dot
            if num_str.startswith('.') or num_str.endswith('.'):
                raise ValueError(f"Invalid number format: {num_str}")
            tokens.append(Token('NUMBER', float(num_str)))
            continue
        if c.isalpha() or c == '_':
            start = i
            while i < len(expr) and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            name = expr[start:i]
            tokens.append(Token('NAME', name))
            continue
        if c in '+-*/^()':
            tokens.append(Token(c, c))
            i += 1
            continue
        raise ValueError(f"Unknown character: {c}")
    return tokens

def parse(tokens: List[Token], variables: Dict[str, float]) -> Tuple[float, int]:
    pos = [0]

    def peek() -> Optional[Token]:
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume() -> Token:
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def parse_primary() -> float:
        t = peek()
        if not t:
            raise ValueError("Missing operand")

        if t.type == 'NUMBER':
            consume()
            return t.value

        if t.type == 'NAME':
            name = t.value
            consume()
            if name not in variables:
                raise ValueError(f"Unknown name: {name}")
            val = variables[name]
            # Check for implicit multiplication with next token
            next_t = peek()
            if next_t and next_t.type == 'NUMBER':
                raise ValueError("Implicit multiplication")
            return val

        if t.type == 'LPAREN':
            consume() # '('
            val, _ = parse_expression()
            t = peek()
            if not t or t.type != 'RPAREN':
                raise ValueError("Unbalanced parentheses")
            consume() # ')'
            return val

        if t.type == 'MINUS':
            consume()
            val = -parse_primary()
            return val

        if t.type == 'PLUS':
            consume()
            return parse_primary()

        raise ValueError(f"Unexpected token: {t}")

    def parse_power() -> float:
        left = parse_primary()
        t = peek()
        if t and t.type == 'CARET':
            consume()
            right = parse_power() # Right associative
            return left ** right
        return left

    def parse_mul_div() -> float:
        left = parse_power()
        while True:
            t = peek()
            if not t:
                break
            if t.type == 'STAR':
                consume()
                right = parse_power()
                left *= right
            elif t.type == 'SLASH':
                consume()
                right = parse_power()
                if right == 0:
                    raise ValueError("Division by zero")
                left /= right
            else:
                break
        return left

    def parse_add_sub() -> float:
        left = parse_mul_div()
        while True:
            t = peek()
            if not t:
                break
            if t.type == 'PLUS':
                consume()
                right = parse_mul_div()
                left += right
            elif t.type == 'MINUS':
                consume()
                right = parse_mul_div()
                left -= right
            else:
                break
        return left

    def parse_function_call() -> float:
        t = peek()
        if not t or t.type != 'NAME':
            raise ValueError(f"Expected function name, got {t}")

        func_name = consume().value
        if func_name not in ('min', 'max', 'abs'):
            raise ValueError(f"Unknown function: {func_name}")

        args = []
        t = peek()
        if not t or t.type != 'LPAREN':
            raise ValueError("Expected '(' after function name")
        consume() # '('

        while True:
            arg, _ = parse_expression()
            args.append(arg)
            t = peek()
            if not t or t.type == 'RPAREN':
                break
            if t.type != 'COMMA':
                raise ValueError("Expected ',' between arguments")
            consume() # ','

        t = peek()
        if not t or t.type != 'RPAREN':
            raise ValueError("Unbalanced parentheses in function call")
        consume() # ')'

        if func_name == 'abs' and len(args) != 1:
            raise ValueError(f"Function abs expects exactly 1 argument, got {len(args)}")
        if func_name in ('min', 'max') and len(args) < 1:
            raise ValueError(f"Functions min/max expect at least 1 argument, got {len(args)}")

        if func_name == 'abs':
            return abs(args[0])
        elif func_name == 'min':
            return min(args)
        else: # max
            return max(args)

    def parse_expression() -> Tuple[float, int]:
        val = parse_add_sub()
        t = peek()
        if not t:
            return val, 0
        if t.type == 'COMMA':
            raise ValueError("Unexpected comma at top level")
        # Check for trailing garbage
        while t and (t.type in ('NUMBER', 'NAME', 'PLUS', 'MINUS', 'STAR', 'SLASH', 'CARET', 'LPAREN')):
             raise ValueError(f"Trailing garbage after expression: {t.value}")
        return val, 0

    if not tokens:
        raise ValueError("Empty expression")

    result, _ = parse_expression()
    if pos[0] != len(tokens):
        raise ValueError("Trailing garbage in expression")

    return result

class OutOfStock(Exception):
    pass


class Inventory:
    def __init__(self, stock=None):
        self._stock = dict(stock) if stock is not None else {}

    def stock(self, item):
        return self._stock.get(item, 0)

    def add(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        current = self.stock(item)
        if current < qty:
            raise OutOfStock()
        self._stock[item] = current - qty


def fulfil(inventory, order):
    total = 0
    for item, qty in order.items():
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        try:
            inventory.remove(item, qty)
            total += qty
        except OutOfStock:
            return total
    return total

